Lemma stepA lo hi raA : runA lo hi raA -> lo <= n <= hi -> L5.ra_ok raA ->
  (forall (fx2 : FPState) R2 M2 md2 LK2 Aw2 cr2 k2, INV M2 md2 LK2 Aw2 cr2 k2 1 -> inregs R2 sp (PMSPA.o_v AD fb) n -> csk R2 ->
